pub fn formatTime(self: ShellLsTask, timestamp: i64, now_secs: u64) [12]u8 {
        _ = &self;
            var buf: [12]u8 = undefined;
            _ = &buf;
            const epoch_secs: u64 = (if ((timestamp < 0)) 0 else @intCast(timestamp));
            const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_secs };
            const day_seconds = epoch.getDaySeconds();
            const year_day = epoch.getEpochDay().calculateYearDay();
            const month_names: [12][]const u8 = .{ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
            const month_day = year_day.calculateMonthDay();
            const month_name = month_names[@as(usize, @intCast((month_day.month.numeric() - 1)))];
            const six_months_secs: u64 = (((180 * 24) * 60) * 60);
            const is_recent = ((epoch_secs > (now_secs -| six_months_secs)) and (epoch_secs <= (now_secs + six_months_secs)));
            if (is_recent) {
                const hours = day_seconds.getHoursIntoDay();
                const minutes = day_seconds.getMinutesIntoHour();
                _ = (blk_catch_0: { break :blk_catch_0 ((std.fmt.bufPrint((&buf), "{s} {d:0>2} {d:0>2}:{d:0>2}", .{ month_name, (month_day.day_index + 1), hours, minutes })) catch |__ce_0| { _ = &__ce_0; break :blk_catch_0 @memcpy((&buf), "??? ?? ??:??"); }); });
            } else {
                const year = year_day.year;
                _ = (blk_catch_1: { break :blk_catch_1 ((std.fmt.bufPrint((&buf), "{s} {d:0>2}  {d:4}", .{ month_name, (month_day.day_index + 1), year })) catch |__ce_1| { _ = &__ce_1; break :blk_catch_1 @memcpy((&buf), "??? ??  ????"); }); });
            }
            return buf;
    }

pub fn addDotEntriesIfNeeded(self: *ShellLsTask, dir_fd: bun.FD) void {
            _ = self.addEntry(".", dir_fd);
            _ = self.addEntry("..", dir_fd);
    }

pub fn errorWithPath(self: *ShellLsTask, err: Syscall.Error, path: [:0]const u8) Syscall.Error {
            _ = debug("Ls(0x{x}).errorWithPath({s})", .{ @intFromPtr(self), path });
            return err.withPath(bun.handleOom(self.ls.alloc_scope.allocator().dupeZ(u8, path[0..path.len])));
    }

pub fn workPoolCallback(task: *jsc.WorkPoolTask) void {
            var this: *ShellLsTask = @fieldParentPtr("task", task);
            _ = &this;
            _ = this.run();
            _ = this.doneLogic();
    }

pub fn doneLogic(self: *ShellLsTask) void {
            _ = debug("Done", .{});
            if ((self.event_loop == .js)) {
                _ = self.event_loop.js.enqueueTaskConcurrent(self.concurrent_task.js.@"from"(self, .manual_deinit));
            } else {
                _ = self.event_loop.mini.enqueueTaskConcurrent(self.concurrent_task.mini.@"from"(self, "runFromMainThreadMini"));
            }
    }

pub fn takeOutput(self: *ShellLsTask) std.array_list.Managed(u8) {
            const ret = self.output;
            self.output = std.array_list.Managed(u8).init(self.ls.alloc_scope.allocator());
            return ret;
    }

pub fn runFromMainThread(self: *ShellLsTask) void {
            _ = debug("runFromMainThread", .{});
            _ = self.ls.onShellLsTaskDone(self);
    }

pub fn runFromMainThreadMini(self: *ShellLsTask) void {
            _ = self.runFromMainThread();
    }

pub fn deinit(self: *ShellLsTask) void {
            _ = debug("deinit {s}", .{ "free" });
            if (self.owned_string) {
                _ = self.ls.alloc_scope.allocator().free(self.path);
            }
            if (self.err) |*err_ptr| {
                _ = &err_ptr;
                _ = (err_ptr.*).deinitWithAllocator(self.ls.alloc_scope.allocator());
            }
            _ = self.output.deinit();
            _ = self.ls.alloc_scope.allocator().destroy(self);
    }
};

pub const Ls = @This();

opts: Opts = .{},
state: State = .idle,
alloc_scope: shell.AllocScope,

pub fn start(self: *Ls) Yield {
        return self.next();
}

pub fn writeFailingError(self: *Ls, buf: []const u8, exit_code: ExitCode) Yield {
        if (self.bltn().stderr.needsIO()) |safeguard| {
            _ = &safeguard;
            self.state = .waiting_write_err;
            return self.bltn().stderr.enqueue(self, buf, safeguard);
        }
        _ = self.bltn().writeNoIO(.stderr, buf);
        return self.bltn().done(exit_code);
}

pub fn next(self: *Ls) Yield {
        while ((!(self.state == .done))) {
            switch (self.state) {
.idle => {
const paths_opt = (switch (self.parseOpts()) {
.ok => |paths| paths,
.err => |e| {
{
                const buf = (switch (e) {
.illegal_option => |opt_str| self.bltn().fmtErrorArena(.ls, "illegal option -- {s}\n", .{ opt_str }),
.show_usage => Builtin.Kind.ls.usageString(),
});
                return self.writeFailingError(buf, 1);
            }
},
});
            var task_count: usize = 1;
            _ = &task_count;
            if (paths_opt) |p| {
                _ = &p;
                task_count = p.len;
            }
            self.state = .{ .exec = .{ .task_count = std.atomic.Value(usize).init(task_count) } };
            const cwd = self.bltn().cwd;
            if (paths_opt) |p| {
                _ = &p;
                const print_directory = (p.len > 1);
                for (cp_iter_slice(p)) |path_raw| {
                    _ = &path_raw;
                    const path = bun.handleOom(self.alloc_scope.allocator().dupeZ(u8, path_raw[0..std.mem.len(path_raw) :0]));
                    var task = ShellLsTask.create(self, self.opts, (&self.state.exec.task_count), cwd, path, true, self.bltn().eventLoop());
                    _ = &task;
                    task.print_directory = print_directory;
                    _ = task.schedule();
                }
            } else {
                var task = ShellLsTask.create(self, self.opts, (&self.state.exec.task_count), cwd, ".", false, self.bltn().eventLoop());
                _ = &task;
                _ = task.schedule();
            }
},
.exec => {
_ = log("Ls(0x{x}, state=exec) Check: tasks_done={d} task_count={d} output_done={d} output_waiting={d}", .{ @intFromPtr(self), self.state.exec.tasks_done, self.state.exec.task_count.load(.monotonic), self.state.exec.output_done, self.state.exec.output_waiting });
            if (((self.state.exec.tasks_done >= self.state.exec.task_count.load(.monotonic)) and (self.state.exec.output_done >= self.state.exec.output_waiting))) {
                const exit_code: ExitCode = (if ((self.state.exec.err != null)) (if (comptime @typeInfo(ExitCode) == .@"enum") @as(ExitCode, @enumFromInt(1)) else @as(ExitCode, 1)) else (if (comptime @typeInfo(ExitCode) == .@"enum") @as(ExitCode, @enumFromInt(0)) else @as(ExitCode, 0)));
                if (self.state.exec.err) |*e| {
                    _ = &e;
                    _ = (e.*).deinitWithAllocator(self.alloc_scope.allocator());
                }
                self.state = .done;
                return self.bltn().done(exit_code);
            }
            return .suspended;
},
.waiting_write_err => {
return .failed;
},
.done => {
_ = unreachable;
},
}
        }
        return self.bltn().done(0);
}

pub fn deinit(self: *Ls) void {
        _ = self.alloc_scope.endScope();
}

pub fn onIOWriterChunk(self: *Ls, e: ?jsc.SystemError) Yield {
        if (e) |err| {
            _ = &err;
            _ = err.deref();
        }
        if ((self.state == .waiting_write_err)) {
            return self.bltn().done(1);
        }
        self.state.exec.output_done = (self.state.exec.output_done + 1);
        return self.next();
}

pub fn onShellLsTaskDone(self: *Ls, task: *ShellLsTask) void {
        self.state.exec.tasks_done = (self.state.exec.tasks_done + 1);
        var output = task.takeOutput();
        _ = &output;
        _ = self.alloc_scope.leakSlice(output.items);
        const unmanaged = output.moveToUnmanaged();
        const output_task: *ShellLsOutputTask = bun.new(ShellLsOutputTask, .{ .parent = self, .output = .{ .arrlist = unmanaged }, .state = .waiting_write_err });
        if (task.err) |*err_ptr| {
            _ = &err_ptr;
            var error_string: []const u8 = "";
            _ = &error_string;
            if ((self.state.exec.err == null)) {
                self.state.exec.err = (err_ptr.*).*;
                error_string = self.bltn().taskErrorToString(.ls, self.state.exec.err.?);
            } else {
                var e = (err_ptr.*).*;
                _ = &e;
                defer {
                _ = e.deinitWithAllocator(self.alloc_scope.allocator());
                }
                error_string = self.bltn().taskErrorToString(.ls, e);
            }
            task.err = null;
            _ = task.deinit();
            _ = output_task.start(error_string).run();
            return;
        }
        _ = task.deinit();
        _ = output_task.start(null).run();
}

pub fn parseOpts(self: *Ls) Result(FilepathArgs,Opts.ParseError) {
        return self.parseFlags();
}

pub fn parseFlags(self: *Ls) Result(FilepathArgs,Opts.ParseError) {
        const args = self.bltn().argsSlice();
        var idx: usize = 0;
        _ = &idx;
        if ((args.len == 0)) {
            return .{ .ok = null };
        }
        while ((idx < args.len)) : (idx = (idx + 1)) {
            const flag = args[@as(usize, @intCast(idx))];
            switch (self.parseFlag(flag[0..std.mem.len(flag)])) {
.done => {
const filepath_args = args[idx..];
            return .{ .ok = filepath_args };
},
.continue_parsing => {

},
.illegal_option => |opt_str| {
return .{ .err = .{ .illegal_option = opt_str } };
},
}
        }
        return .{ .ok = null };
}

pub fn parseFlag(self: *Ls, flag: []const u8) ParseFlagResult {
        if ((flag.len == 0)) {
            return .done;
        }
        if ((flag[0] != 45)) {
            return .done;
        }
        const small_flags = flag[1..];
        for (cp_iter_slice(small_flags)) |char| {
            _ = &char;
            switch (char) {
'a' => {
self.opts.show_all = true;
},
'A' => {
self.opts.show_almost_all = true;
},
'b' => {
self.opts.escape = true;
},
'B' => {
self.opts.ignore_backups = true;
},
'c' => {
self.opts.use_ctime = true;
},
'C' => {
self.opts.list_by_columns = true;
},
'd' => {
self.opts.list_directories = true;
},
'D' => {
self.opts.dired_mode = true;
},
'f' => {
self.opts.unsorted = true;
},
'F' => {
self.opts.classify = "always";
},
'g' => {
self.opts.no_owner = true;
},
'G' => {
self.opts.no_group = true;
},
'h' => {
self.opts.human_readable = true;
},
'H' => {
self.opts.dereference_cmd_symlinks = true;
},
'i' => {
self.opts.show_inode = true;
},
'I' => {
self.opts.ignore_pattern = "";
},
'k' => {
self.opts.kibibytes = true;
},
'l' => {
self.opts.long_listing = true;
},
'L' => {
self.opts.dereference = true;
},
'm' => {
self.opts.comma_separated = true;
},
'n' => {
self.opts.numeric_uid_gid = true;
},
'N' => {
self.opts.literal = true;
},
'o' => {
self.opts.no_group_info = true;
},
'p' => {
self.opts.slash_indicator = true;
},
'q' => {
self.opts.hide_control_chars = true;
},
'Q' => {
self.opts.quote_name = true;
},
'r' => {
self.opts.reverse_order = true;
},
'R' => {
self.opts.recursive = true;
},
's' => {
self.opts.show_size = true;
},
'S' => {
self.opts.sort_by_size = true;
},
't' => {
self.opts.sort_by_time = true;
},
'T' => {
self.opts.tabsize = 8;
},
'u' => {
self.opts.use_atime = true;
},
'U' => {
self.opts.no_sort = true;
},
'v' => {
self.opts.natural_sort = true;
},
'w' => {
self.opts.output_width = 0;
},
'x' => {
self.opts.list_by_lines = true;
},
'X' => {
self.opts.sort_by_extension = true;
},
'Z' => {
self.opts.show_context = true;
},
'1' => {
self.opts.one_file_per_line = true;
},
else => {
return .{ .illegal_option = flag[1..2] };
},
}
        }
        return .continue_parsing;
}

pub inline fn bltn(self: *Ls) *Builtin {
        const impl_: *Builtin.Impl = @alignCast(@fieldParentPtr("ls", self));
        return @fieldParentPtr("impl", impl_);
}
